books["929dd843"] = { d = 42.3, v = "narrator", c = { x = { { 0.00, "Аукиндон — древний некрополь дренеев в сердце Леса Тероккар, построенный вокруг священных погребальных залов." }, { 11.69, "Сюда веками приносили тела умерших, чтобы души могли найти покой и уйти за пределы мира." }, { 20.45, "После падения Дренора подземелья заняли огры, призванные духи и демоны, а разломы в ткани мира выпустили наружу беспокойные души." }, { 32.81, "В разных залах идут свои войны, но все они угрожают памяти дренеев и тем, кто пытается защитить это место." } } } }
books["c55306bc"] = { d = 45.2, v = "narrator", c = { x = { { 0.00, "Борейская тундра — плоский и продуваемый край на юго-западе Нордскола, где холодные равнины сходятся с морем." }, { 10.63, "Альянс и Орда высадились здесь почти одновременно: Крепость Отваги и Крепость Песни Войны стали опорными пунктами войны с Королём-личом." }, { 23.77, "Тускарры Каскалы ищут убежище в Уну'пе после нападений нагов и квалдиров, а таунка помогают Орде вспомнить древнее родство с тауренами." }, { 36.53, "На севере драконы синего цвета и Кирин'Тор сражаются за Хладарру, где пробудился Малигос." } } } }
books["31e2d7c6"] = { d = 32.4, v = "narrator", c = { x = { { 0.00, "Взлётная полоса Выкрутеня — инженерная база Альянса среди снегов Борейской тундры." }, { 9.08, "Гномы строят здесь летательные машины, ремонтируют оборудование и поддерживают связь между отдалёнными лагерями." }, { 18.50, "За шумом мастерских скрывается военная работа: инженеры помогают экспедиции удерживать дороги и противостоять Орде, Плети и опасностям ледяного континента." } } } }
books["aef8a5cf"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "Деревня Таунка'ле — поселение таунка на востоке Борейской тундры." }, { 7.00, "Её жители хранят древние обычаи и помогают Орде выжить в краю, где холод и война одинаково опасны." }, { 16.70, "Из деревни уходят охотники и воины, защищающие родичей от Плети, нагов и чужих армий, пришедших делить Нордскол." } } } }
books["5f30b64b"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Застава Бор'горока — северный опорный пункт Орды в Борейской тундре." }, { 7.62, "Орки и таунка следят отсюда за дорогами к ледяным полям, собирают припасы и готовят вылазки против врагов экспедиции." }, { 18.19, "Застава соединяет южные крепости с дальними маршрутами Нордскола и остаётся одним из главных рубежей Орды на тундровом берегу." } } } }
books["4301e262"] = { d = 32.5, v = "narrator", c = { x = { { 0.00, "Каскала — древнее поселение тускарров на берегу Борейской тундры." }, { 7.10, "Когда наги и квалдиры напали на деревню, жители были вынуждены покинуть свои дома и искать спасения в Уну'пе." }, { 16.93, "Пустые хижины и следы недавней битвы напоминают, что тускарры не отказались от родной земли." }, { 24.52, "Для них Каскала остаётся не просто стоянкой, а домом, который однажды предстоит вернуть." } } } }
books["4583890f"] = { d = 38.8, v = "narrator", c = { x = { { 0.00, "Крепость Отваги — главная база Альянса на южном берегу Борейской тундры." }, { 8.67, "Сюда прибывают корабли со Штормграда, доставляя солдат, припасы и разведчиков для войны с Королём-личом." }, { 19.15, "За стенами работают инженеры, лекари и командиры экспедиции, а за воротами идут бои с Плетью и нагами." }, { 30.62, "Крепость остаётся одним из первых мест, где силы Альянса закрепились на ледяном континенте." } } } }
books["503529ce"] = { d = 39.9, v = "narrator", c = { x = { { 0.00, "Крепость Песни Войны — укрепление Орды на юге Борейской тундры, построенное для наступления на Плеть." }, { 10.64, "В её стенах собираются орки, таунка и другие воины экспедиции, а с башни дирижаблей поддерживается связь с Калимдором." }, { 22.16, "Гарнизон следит за дорогами к Наксанару и ледяным берегам, где враг прячет свои войска." }, { 29.95, "Крепость живёт в постоянной готовности, потому что северные равнины не дают Орде ни времени, ни безопасного тыла." } } } }
books["ff9ab166"] = { d = 28.1, v = "narrator", c = { x = { { 0.00, "Маскировочный щит — магическая площадка на Хладарре, связанная с обороной Нексуса и исследованиями Кирин'Тора." }, { 10.81, "Здесь смертные пытаются удержать проходы к владениям Малигоса и следят за движением синей стаи." }, { 20.19, "Лёд вокруг скрывает не спокойную заставу, а передний край войны за саму силу магии." } } } }
books["077e2c0e"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Нексус — древняя крепость синей стаи в центре Хладарры." }, { 6.42, "Когда-то её залы служили убежищем драконов и местом хранения знаний о магии, но после пробуждения Малигоса крепость стала сердцем его войны." }, { 20.54, "Внутри сражаются драконы, маги Кирин'Тора и существа, искажённые арканной энергией." }, { 29.66, "Каждый коридор Нексуса ведёт к силе, которой Малигос хочет подчинить всю магию мира." } } } }
books["438d4a61"] = { d = 38.0, v = "narrator", c = { x = { { 0.00, "Уну'пе — прибрежное поселение тускарров на востоке Борейской тундры." }, { 7.90, "После нападения на Каскалу сюда переселились многие её жители, превратив рыбацкую стоянку в убежище для целого народа." }, { 19.63, "Тускарры чинят лодки, ловят рыбу и поддерживают связь с другими портами Нордскола." }, { 27.37, "Отсюда черепашьи корабли уходят к Драконьему Погосту, а память о потерянной Каскале не даёт поселению стать обычной гаванью." } } } }
books["178cffb2"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Хладарра — холодный остров на западе Борейской тундры, где сосредоточилась сила синей стаи драконов." }, { 9.52, "В его центре возвышается Нексус, древняя крепость Малигоса и источник опасных магических потоков." }, { 18.09, "Кирин'Тор пытается остановить дракона, который объявил смертных угрозой для самой магии." }, { 25.49, "Лёд острова скрывает не только драконьи залы, но и следы войны, способной изменить равновесие Азерота." } } } }
books["c7c4323b"] = { d = 31.6, v = "narrator", c = { x = { { 0.00, "Янтарная гряда — прибрежная стоянка на западе Борейской тундры, где экспедиции встречают ледяное море и дороги к Хладарре." }, { 11.82, "Здесь закрепились маги и разведчики, изучающие северные берега и следы синей стаи драконов." }, { 21.29, "Небольшая гавань стала важной остановкой для тех, кто движется между опорными пунктами Альянса, Орды и Кирин'Тора." } } } }
books["89a5de48"] = { d = 40.8, v = "narrator", c = { x = { { 0.00, "Акерус: Черный оплот — некрополь и главная база рыцарей Черного клинка." }, { 8.38, "В дни службы Королю-личу отсюда рыцари смерти отправляются против Алого ордена, а в его сердце работают рунические кузницы и некроманты." }, { 20.87, "Поднятый над Восточными Чумными землями Акерус хранит память о прежних хозяевах и готовит своих воинов к разрыву с Плетью." }, { 31.90, "Для нового рыцаря смерти это не просто крепость, а место, где начинается путь к собственной воле." } } } }
books["afe32b65"] = { d = 36.3, v = "narrator", c = { x = { { 0.00, "Разлом Смерти — передовая крепость Плети в Алом анклаве." }, { 6.42, "Из этого укрепления нежить давит на дороги, фермы и заставы Алого ордена, превращая окрестности в постоянное поле боя." }, { 17.69, "Для рыцарей смерти это рубеж, где служба Королю-личу становится настоящим наступлением." }, { 26.54, "После падения Разлома Смерти путь к Светлой Надежде открывается, но цена победы только начинает проявляться." } } } }
books["6279f66c"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "Тихоземская лесопилка снабжает Алый орден древесиной для стен, башен и осадных работ." }, { 7.89, "Здесь трудятся рабочие под охраной крестоносцев, не замечая, как фронт подступает к самой деревне." }, { 18.73, "В цепочке рыцаря смерти лесопилка становится одной из уязвимых точек Алого анклава." }, { 26.11, "Удар по снабжению открывает дорогу к его сердцу." } } } }
books["5ec7c47c"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Тихоземская шахта даёт Алому ордену руду для оружия и укреплений." }, { 7.45, "Под землёй рабочие продолжают добычу, пока наверху крестоносцы готовятся к осаде и новым нападениям." }, { 16.95, "Для Плети шахта важна как источник металла и как место, где можно ударить по тылу врага." }, { 25.28, "Разрушение её работы лишает Алый анклав части сил перед решающей атакой." } } } }
books["0adbc29e"] = { d = 38.2, v = "narrator", c = { x = { { 0.00, "Тихоземские стойла держат лошадей, на которых Алый орден патрулирует деревню и ближайшие дороги." }, { 9.51, "Для крестоносцев конь означает связь между заставами, а для Короля-лича — ещё один ресурс, который можно отнять или обратить против хозяев." }, { 23.61, "Здесь рыцари смерти сталкиваются с тем, как быстро привычный порядок рушится под натиском Плети." }, { 33.04, "Путь через стойла ведёт войну прямо к воротам Тихоземья." } } } }
books["0fef2698"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "Тихоземские фермы кормят гарнизон Алого ордена и служат ему мирной маской." }, { 8.04, "Между амбарами и полями крестьяне стараются жить обычной жизнью, пока неподалёку собираются мёртвые армии." }, { 18.27, "Для Плети эти поля — удобная цель, а для рыцарей смерти — напоминание, что война Короля-лича приходит не только в крепости." }, { 29.83, "Каждый разрушенный двор ослабляет оборону Тихоземья." } } } }
books["33747549"] = { d = 35.7, v = "narrator", c = { x = { { 0.00, "Тихоземье — деревня Алого ордена в инстансной версии Восточных Чумных земель." }, { 7.72, "За частоколом крестоносцы держат дома, поля и дороги, уверенные, что очищают Лордерон от нежити." }, { 17.31, "Для рыцарей смерти это первая живая земля, которую предстоит превратить в поле войны." }, { 25.72, "Здесь особенно ясно видно, что Алый орден боится не только Плети, но и самой возможности возвращения павших." } } } }
books["d18bf24e"] = { d = 43.0, v = "narrator", c = { x = { { 0.00, "Грозовая Гряда — суровые горы на северо-востоке Нордскола, где метели скрывают следы титанов и древних империй." }, { 11.92, "В глубине хребта стоит Ульдуар, крепость, превращённая Йогг-Сароном в тюрьму для живых и мёртвых." }, { 21.69, "Железные дворфы куют армию для своих создателей, а Бранн Бронзобород пытается понять тайны прошлого Азерота." }, { 32.71, "На вершинах валькиры и ледяные великаны ведут свою войну, пока Сыны Ходира решают, кому доверить защиту гор." } } } }
books["29d27a4f"] = { d = 30.4, v = "narrator", c = { x = { { 0.00, "Дун Ниффелем — древнее поселение ледяных великанов в сердце Грозовой Гряды." }, { 8.23, "Сыны Ходира жили здесь задолго до прихода смертных, но война с железными дворфами и Плетью заставила их искать новых союзников." }, { 19.65, "За стенами поселения куют оружие, вспоминают старые клятвы и готовят защиту гор от тех, кто хочет подчинить их наследие." } } } }
books["06b4a3b6"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "К-три — гоблинская стоянка на высоких перевалах Грозовой Гряды." }, { 6.91, "Торговцы и инженеры пытаются заработать на экспедициях, снабжая их топливом, механизмами и сомнительными советами." }, { 16.90, "За шумом мастерских скрываются древние руины, железные дворфы и дороги к Ульдуару, поэтому даже деловой лагерь живёт в постоянном ожидании опасности." } } } }
books["5d3bd3b9"] = { d = 29.1, v = "narrator", c = { x = { { 0.00, "Лагерь Тунка’ло — поселение таунка на заснеженных склонах Грозовой Гряды." }, { 8.15, "Ордынская экспедиция использует его как базу для разведки гор и поиска союзников среди древних народов Нордскола." }, { 17.66, "Воины лагеря следят за дорогами к Ульдуару и помогают таунка сохранить свою культуру в краю, где титаны и Плеть одинаково опасны." } } } }
books["55b28843"] = { d = 29.4, v = "narrator", c = { x = { { 0.00, "Ледяная крепость — главная база дворфов Братства Стали в Грозовой Гряде." }, { 8.52, "Здесь Альянс принимает разведчиков, готовит походы к Ульдуару и изучает тайны титанов, скрытые под снегом." }, { 18.96, "Крепость стоит на краю обрывов, где железные враги и древние хранители одинаково следят за каждым приближением." } } } }
books["3d7c1f80"] = { d = 30.4, v = "narrator", c = { x = { { 0.00, "Место крушения Гром'арша — лагерь Орды среди ледяных склонов Грозовой Гряды." }, { 8.82, "После аварии воздушного корабля выжившие собирают оборудование, укрепляют стоянку и пытаются понять, как продолжить поход в горах." }, { 21.16, "Отсюда разведчики отправляются к поселениям титанов, лагерям дворфов и дорогам, ведущим к Ульдуару." } } } }
books["6b13ad86"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Приют Глыбоскала — стоянка исследователей у южных склонов Грозовой Гряды." }, { 7.60, "Здесь экспедиции изучают железных дворфов, следят за дорогой к Ульдуару и собирают сведения о наследии титанов." }, { 17.23, "Скалы вокруг кажутся безжизненными, но под ними продолжается работа древних механизмов и подготовка новой войны." } } } }
books["0c4c273a"] = { d = 33.6, v = "narrator", c = { x = { { 0.00, "Ульдуар — титаническая крепость в глубине Грозовой Гряды." }, { 6.69, "Когда-то здесь содержали опасных созданий и хранили знания о мире, но Йогг-Сарон исказил её хранителей и превратил комплекс в источник безумия." }, { 21.57, "Экспедиции пытаются пробиться за древние врата, чтобы остановить древнего бога и понять, какую роль Ульдуар играл в создании Азерота." } } } }
books["08342fae"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Даларан — парящий город магов над Лесом Хрустальной Песни и главный союзный опорный пункт Нордскола." }, { 7.21, "Кирин'Тор перенёс его на север, чтобы сдержать Малигоса и помочь войскам Альянса и Орды в войне с Королём-личом." }, { 15.29, "На улицах встречаются герои всех народов, а в святилищах Серебряного союза и Похитителей Солнца продолжается старое политическое противостояние." }, { 25.67, "Под городом Аметистовая крепость хранит опасных пленников, а через порталы маги связывают Нордскол с остальным Азеротом." } } } }
books["dfdf240b"] = { d = 20.0, v = "narrator", c = { x = { { 0.00, "Вечерняя Заря — спокойный район на окраине Даларана, где путешественники могут перевести дух после дороги." }, { 7.82, "Здесь меньше магических башен и боевых посланников, зато хорошо видно, как парящий город живёт обычной жизнью." }, { 15.94, "За воротами начинается путь к другим районам Нордскола." } } } }
books["1ba3da02"] = { d = 23.5, v = "narrator", c = { x = { { 0.00, "Даларан — парящий город магов над Лесом Хрустальной Песни и главный союзный опорный пункт Нордскола." }, { 7.47, "Кирин'Тор перенёс его на север, чтобы сдержать Малигоса и помочь войскам Альянса и Орды в войне с Королём-личом." }, { 15.83, "На улицах встречаются герои всех народов, а через порталы маги связывают Нордскол с остальным Азеротом." } } } }
books["6914284c"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Клоака — тёмное подземелье под Далараном, где сходятся контрабандисты, наёмники и те, кто не хочет показываться на свету." }, { 8.94, "Здесь работают торговцы редкостями, а в Круге Воли бойцы выясняют отношения на арене." }, { 15.22, "Даже под защитой Кирин-Тора этот угол города живёт по своим законам." } } } }
books["17bb7d21"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Памятник Антонидасу напоминает жителям Даларана о великом архимаге и последнем защитнике старого города." }, { 8.26, "Вокруг памятника маги и ученики Кирин-Тора вспоминают падение Даларана и тех, кто погиб, сдерживая Плеть." }, { 16.60, "Это место тише городских площадей, но его история чувствуется особенно остро." } } } }
books["15579f21"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "Площадка Краса — воздушная гавань Даларана и место прибытия драконов и воздушных кораблей." }, { 6.54, "Отсюда открывается вид на Лес Хрустальной Песни, а путешественники отправляются к главным крепостям Нордскола." }, { 14.53, "На площадке всегда слышны команды погонщиков и шум прибывающих путников." } } } }
books["fc4ae9e0"] = { d = 19.9, v = "narrator", c = { x = { { 0.00, "Площадь Руноплета — центральная площадь Даларана, где магические руны светятся прямо под ногами прохожих." }, { 7.75, "Отсюда легко добраться к главным башням, торговым улицам и порталам города." }, { 13.28, "Здесь постоянно встречаются искатели приключений, посланники фракций и ученики Кирин-Тора." } } } }
books["0c5aa35e"] = { d = 18.5, v = "narrator", c = { x = { { 0.00, "Прибежище Похитителя Солнца — штаб Похитителей Солнца и главная опора Орды в Даларане." }, { 6.43, "Кровавые эльфы следят здесь за интересами Кель'Таласа, принимают посланников и готовят магов к войне." }, { 13.99, "Напряжение с Серебряным союзом ощущается в каждом разговоре." } } } }
books["296d902f"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Серебряный Союз — крепость и посольство Альянса в Даларане." }, { 4.48, "Здесь высшие эльфы и их союзники наблюдают за Похитителями Солнца, защищают интересы своей фракции и поддерживают порядок в городе." }, { 14.41, "За стенами квартала магическая борьба превращается в политическое противостояние." } } } }
books["791cc92e"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Торговая палата волшебников — шумный рынок Даларана, где продают оружие, броню, реагенты и магические товары со всего Азерота." }, { 9.64, "Здесь собираются ремесленники и путешественники, а над прилавками постоянно вспыхивают чары." }, { 16.68, "Это самое оживлённое место города после Площади Руноплета." } } } }
books["a72cde7e"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Укрытие Варгота — тихий уголок Даларана, связанный с башней мага и его странными исследованиями." }, { 7.34, "Здесь меньше торгового шума, зато чаще встречаются магические артефакты и следы старых экспериментов." }, { 15.06, "Даже в таком безопасном городе не всякая тайна Кирин-Тора лежит на виду." } } } }
books["871df31a"] = { d = 43.5, v = "narrator", c = { x = { { 0.00, "Долина Призрачной Луны лежит на юго-востоке Запределья, среди чёрных скал и вулканических пустошей." }, { 10.27, "Когда-то здесь жил клан Призрачной Луны, а его вождь Нер'зул открыл порталы, разорвавшие Дренор." }, { 19.53, "Теперь над долиной нависает Цитадель Черного храма, где Иллидан Ярость Бури правит демонами, нагами и предавшимися ему эльфами крови." }, { 31.98, "Внизу сражаются силы Альянса и Орды, драконы Пустоты охраняют свои гнёзда, а древние руины напоминают о цене колдовства." } } } }
books["ab4c60b3"] = { d = 44.5, v = "narrator", c = { x = { { 0.00, "Деревня Призрачной Луны стоит у побережья в южной части долины и служит опорным пунктом Орды." }, { 10.84, "Здесь собираются разведчики, охотники и шаманы, которые ищут сведения о силах Иллидана и о старых кланах орков." }, { 23.15, "За частоколом начинаются чёрные равнины, где в воздухе чувствуется скверна, а драконы Пустоты охраняют свои гнёзда." }, { 35.55, "Деревня помогает Орде удерживать южные дороги, несмотря на постоянные нападения и нехватку припасов." } } } }
books["0a923364"] = { d = 41.2, v = "narrator", c = { x = { { 0.00, "Кряж Крыльев Пустоты — цепь островов и пещер над юго-восточными скалами Долины Призрачной Луны." }, { 10.22, "Здесь скрываются драконы Пустоты, потомки существ, изменённых энергией разорванных миров." }, { 19.41, "Они охраняют кладки, руду и старые тропы, а чужаки приходят сюда ради союзов и редких материалов." }, { 30.01, "Над кряжем постоянно звучит шелест крыльев, и любой договор с его обитателями требует уважения к их свободе и тяжёлому прошлому." } } } }
books["a9f634b6"] = { d = 35.3, v = "narrator", c = { x = { { 0.00, "Святилище Звезд — скрытое поселение эльфов крови в северной части долины." }, { 7.44, "Его жители следят за магическими потоками и наблюдают за врагами Иллидана, сохраняя верность собственным тайным планам." }, { 18.04, "Святилище построено среди чёрных скал, поэтому его трудно заметить с дальних дорог." }, { 24.70, "Здесь встречаются разведчики, маги и торговцы, а рядом проходят пути к цитадели и к местам, где сила Пустоты особенно заметна." } } } }
books["f351cc8e"] = { d = 38.5, v = "narrator", c = { x = { { 0.00, "Форт Легиона — демоническая крепость среди вулканических полей Долины Призрачной Луны." }, { 8.89, "Его гарнизон следит за дорогами, охраняет порталы и поддерживает войска, служащие Пылающему Легиону." }, { 17.85, "Внутри кипит работа над оружием и ритуалами, а снаружи земля покрыта пеплом и следами магических взрывов." }, { 28.03, "Для противников форт становится одной из главных целей, потому что его разрушение может ослабить демоническую сеть по всей долине." } } } }
books["1d62045d"] = { d = 38.6, v = "narrator", c = { x = { { 0.00, "Цитадель Громового Молота — крепость дворфов клана Громового Молота на северных склонах долины." }, { 8.89, "Дворфы охраняют свои шахты, поддерживают воинов Альянса и стараются сохранить порядок среди чёрных камней и вулканического пепла." }, { 20.32, "Из цитадели удобно наблюдать за дорогами к храму и драконьим гнёздам, но близость врага не позволяет расслабиться." }, { 29.75, "За крепкими стенами живут кузнецы, разведчики и семьи, которые пришли в Запределье за новым домом." } } } }
books["17e197af"] = { d = 42.6, v = "narrator", c = { x = { { 0.00, "Драконий Погост — ледяная равнина в центре Нордскола, куда древние драконы приходят умирать." }, { 8.77, "Над костями их предков возвышается Храм Драконьего Покоя, где хранительница жизни Алекстраза собирает стаи перед последней войной." }, { 20.98, "На юге Альянс и Орда спорят за дороги и крепости, а в центре Плеть строит новые некрополи." }, { 30.08, "После предательства у Врат Гнева война стала ещё ожесточённее, и каждое святилище здесь напоминает, что Король-лич угрожает не одному народу." } } } }
books["eb17f5db"] = { d = 27.5, v = "narrator", c = { x = { { 0.00, "Гавань Моа'ки — поселение тускарров на южном берегу Драконьего Погоста." }, { 7.37, "Рыбаки и мореходы поддерживают здесь связь между берегами Нордскола, перевозят путников и помогают сородичам пережить войну." }, { 18.02, "На причалах встречаются представители разных экспедиций, но саму гавань тускарры стараются сохранить мирной и независимой." } } } }
books["77a09911"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "Крепость Стражей Зимы — древнее укрепление Альянса в Драконьем Погосте." }, { 8.28, "Её солдаты изучают следы старых войн, обороняют дороги и сражаются с Плетью, которая поднимает мёртвых вокруг разрушенных поселений." }, { 22.31, "Каменные стены напоминают о прошлом континента, но гарнизон живёт настоящей войной и готовит новые вылазки на север." } } } }
books["4649d0d3"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Крепость Фордрагона — главный опорный пункт Альянса в Драконьем Погосте." }, { 7.28, "Солдаты держат здесь северную дорогу, готовят походы против Плети и принимают вести от экспедиций, разбросанных по ледяной равнине." }, { 18.47, "Крепость стоит напротив владений Орды, поэтому её гарнизон одновременно ведёт войну с нежитью и следит за соседним фронтом." } } } }
books["74f76417"] = { d = 29.4, v = "narrator", c = { x = { { 0.00, "Молот Агмара — крепость Орды в южной части Драконьего Погоста." }, { 6.65, "Здесь орки и таунка собирают силы для войны с Плетью, охраняют дороги и поддерживают связь с другими гарнизонами Нордскола." }, { 17.86, "За стенами кипит военная работа, а вокруг лежат земли, где некрополи и драконьи святилища напоминают о цене затянувшейся войны." } } } }
books["ee5c05e0"] = { d = 28.8, v = "narrator", c = { x = { { 0.00, "Отряд кор'крона — передовая стоянка элитных воинов Орды в северной части Драконьего Погоста." }, { 9.09, "Кор'кроны охраняют подходы к ледяным землям и готовят удары по войскам Плети, действуя от имени вождя Орды." }, { 19.27, "Здесь война лишена мирной оболочки: палатки, оружие и дозоры стоят прямо среди заснеженных дорог." } } } }
books["4dc761ee"] = { d = 26.4, v = "narrator", c = { x = { { 0.00, "Покой Звёзд — небольшая база Альянса среди заснеженных дорог Драконьего Погоста." }, { 8.05, "Разведчики следят отсюда за Плетью, а маги и солдаты поддерживают связь с крепостями на юге и с Храмом Драконьего Покоя." }, { 18.77, "Место кажется тихим лишь издали: рядом проходят маршруты войск, драконов и некрополей." } } } }
books["19a692a7"] = { d = 33.6, v = "narrator", c = { x = { { 0.00, "Храм Драконьего Покоя — древнее святилище в центре Драконьего Погоста и место встречи драконьих стай." }, { 10.98, "Хранительница жизни Алекстраза и её союзники собирают здесь силы перед войной с Малигосом и Королём-личом." }, { 21.27, "Под храмом сходятся пути смертных армий, но для драконов это прежде всего память о предках и последняя надежда на единство." } } } }
books["7465eb24"] = { d = 29.3, v = "narrator", c = { x = { { 0.00, "Ядозлобь — крепость Отрёкшихся в западной части Драконьего Погоста." }, { 7.84, "Алхимики и солдаты Длани Возмездия используют её как плацдарм против Плети и наблюдают за дорогами, ведущими к Седым холмам." }, { 19.01, "Здесь война ведётся не только оружием: лаборатории и бочки с чумой делают крепость опасной для каждого соседнего лагеря." } } } }
books["317276d1"] = { d = 44.2, v = "narrator", c = { x = { { 0.00, "Зангартопь — болотистый край на западе Запределья, где над топями поднимаются исполинские грибы." }, { 10.63, "Когда-то здесь плескалось Зангарское море, но скверна, губившая Дренор, иссушила его, и на месте вод осталась светящаяся трясина." }, { 24.07, "Теперь наги леди Вайш отводят воду болот в Резервуар Кривого Клыка, а огры Анго'рош вырубают грибные леса." }, { 35.24, "Экспедиция Кенария из Кенарийского приюта пытается спасти этот хрупкий край, пока он не погиб окончательно." } } } }
books["eadc638a"] = { d = 40.0, v = "narrator", c = { x = { { 0.00, "Забра'джин — поселение Орды на западной окраине Зангартопи, построенное на деревянных настилах среди воды и гигантских грибов." }, { 10.07, "Здесь собираются разведчики, охотники и искатели руды, которым приходится следить за нагами и агрессивными племенами болотных существ." }, { 22.84, "Из поселения дороги уходят к западным топям и к скрытым подземным резервуарам." }, { 28.92, "Забра'джин держится на постоянной работе: в Зангартопи любая тропа может исчезнуть под водой, а любой союзник — оказаться частью чужого плана." } } } }
books["3b65b564"] = { d = 38.4, v = "narrator", c = { x = { { 0.00, "Застава Болотной Крысы спрятана в северных трясинах Зангартопи, где старые деревянные мосты соединяют островки суши." }, { 10.27, "Контрабандисты, торговцы и наёмники используют её как перевалочный пункт, а путники ищут здесь сведения о дорогах через топи." }, { 21.06, "Вокруг живут опасные звери и племена, которым не нравится присутствие чужаков." }, { 27.91, "Застава кажется шумным убежищем, но за её огнями начинаются места, где вода скрывает руины и следы борьбы за ресурсы болота." } } } }
books["0f04a723"] = { d = 41.1, v = "narrator", c = { x = { { 0.00, "Кенарийский приют стоит у восточных дорог Зангартопи и служит центром работы друидов и следопытов." }, { 10.00, "Экспедиция Кенария изучает, почему болота высыхают, и пытается остановить тех, кто отводит воду к своим механизмам." }, { 20.72, "В приюте наблюдают за гигантскими грибами, лечат раненых и собирают сведения о нагах и ограх." }, { 29.75, "Отсюда начинается путь к затопленным руинам и к местам, где будущее всего болотного края зависит от нескольких каналов." } } } }
books["5fb83f63"] = { d = 41.4, v = "narrator", c = { x = { { 0.00, "Спореггар — маленькое поселение спорлингов в глубине Зангартопи." }, { 6.68, "Эти грибные существа живут среди корней и спор, выращивают пищу и защищают свои места от огров и других захватчиков." }, { 17.50, "Их дома хрупки, но сами спорлинги хорошо знают воду, тропы и свойства болотных растений." }, { 26.68, "Для чужаков Спореггар становится союзником только после помощи его жителям, ведь каждый день поселения связан с поиском припасов и защитой от тех, кто вырубает грибные леса." } } } }
books["8d528d5a"] = { d = 45.5, v = "narrator", c = { x = { { 0.00, "Телредор — поселение дренеев на вершине гигантского гриба в восточной Зангартопи, крупнейший их оплот в этом краю." }, { 10.68, "Столетия назад здесь стояла уединённая обитель отшельников на острове посреди Зангарского моря." }, { 18.31, "Когда орки осадили Шаттрат, пророк Велен привёл сюда уцелевших, и кристаллы, созданные мастерами дренеев, укрыли храм от глаз Орды." }, { 29.65, "Позже именно в Телредоре Сломленный шаман Нобундо начал учить сородичей говорить со стихиями." }, { 37.62, "Ныне здесь собираются силы Альянса, а защитники поселения отражают набеги наг леди Вайш." } } } }
books["09eb45ff"] = { d = 43.2, v = "narrator", c = { x = { { 0.00, "Зул'Драк — суровое царство ледяных троллей на северо-востоке Нордскола." }, { 7.62, "Отчаявшиеся дра'ккари приносят в жертву собственных лоа, надеясь остановить наступление Плети, но эти жертвы лишь разрушают старый порядок." }, { 21.05, "В заброшенных храмах Дракуру собирает армию мёртвых вождей, а Серебряный Авангард удерживает заставу среди снега и руин." }, { 32.95, "Под землёй лежит Гундрак, древний город троллей, где живые боги и нежить борются за последние святилища." } } } }
books["44af77a0"] = { d = 32.7, v = "narrator", c = { x = { { 0.00, "Гундрак — древний город ледяных троллей в северной части Зул'Драка." }, { 7.50, "Его храмы и водные проходы хранят последние владения лоа, но отчаяние толкает дра'ккари к опасным жертвам и союзам." }, { 20.81, "Под стенами города сталкиваются тролли, нежить и чужие экспедиции, каждая из которых ищет путь к силе, скрытой в святилищах." } } } }
books["c536cd14"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Зим'Торга — поселение троллей у дорог северного Зул'Драка, где союзники Серебряного Авангарда ведут борьбу с Плетью и падшими жрецами." }, { 12.38, "Здесь встречаются охотники, разведчики и воины, которым нужны сведения о храмах и старых лоа." }, { 21.13, "Деревня остаётся живым островком среди снега, но вокруг неё война уже добралась до каждого святилища." } } } }
books["8a58777d"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Разлом Света — лагерь Серебряного Авангарда на заснеженном юге Зул'Драка." }, { 9.28, "Крестоносцы удерживают здесь дорогу к храмам троллей и отбиваются от Плети, которая превращает руины в кладбища." }, { 20.82, "Небольшая застава соединяет передовые отряды с Серебряной заставой и служит первым убежищем для тех, кто идёт в глубь ледяного царства." } } } }
books["6957c78a"] = { d = 32.0, v = "narrator", c = { x = { { 0.00, "Серебряная застава — главный опорный пункт Серебряного Авангарда в Зул'Драке." }, { 7.69, "Здесь крестоносцы объединяют силы Альянса, Орды и независимых воинов, чтобы противостоять Плети и безумию ледяных троллей." }, { 19.06, "От заставы дороги ведут к храмам, перевалам и другим лагерям, поэтому её гарнизон постоянно принимает новые отряды и отправляет их на передовую." } } } }
books["7c400a9c"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Чёрная застава — укреплённый пост Серебряного Авангарда на юге Зул'Драка." }, { 8.16, "Крестоносцы следят за Плетью, защищают дороги и собирают сведения о том, как ледяные тролли жертвуют собственными лоа." }, { 19.67, "За стенами заставы сходятся разведчики разных народов, потому что война здесь затрагивает и древние храмы, и будущее всего Нордскола." } } } }
books["212057b3"] = { d = 42.5, v = "narrator", c = { x = { { 0.00, "Круговерть Пустоты — безграничное пространство хаоса между мирами, где расстояние и время подчиняются чужим законам." }, { 11.21, "В её потоках странствуют демоны, рушатся обломки разрушенных миров и открываются порталы в далёкие земли." }, { 20.27, "Пылающий Легион использует Пустоту как дорогу для своих армий, а заклинатели пытаются направить её силу в свои ритуалы." }, { 30.19, "Здесь нет безопасной дороги и нет привычного неба: любой островок материи может оказаться лишь мгновенной остановкой среди бесконечного вихря." } } } }
books["b80e4bc0"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "Лагерь Хротгара — небольшой ледяной берег у северных вод Нордскола, где море встречается с туманом и скалами." }, { 10.48, "Здесь закрепились квалдиры, морские воины, служащие своим жестоким вождям и нападающие на поселения тускарров." }, { 20.64, "Островок редко становится домом для путешественников, но его берега напоминают, что война с Королём-личом идёт не только на суше." }, { 30.97, "Любой корабль в этих водах рискует встретиться с квалдирским флотом." } } } }
books["fb9cbf46"] = { d = 39.6, v = "narrator", c = { x = { { 0.00, "Ледяная Корона — чёрный ледник на севере Нордскола и сердце державы Короля-лича." }, { 8.35, "Над горами поднимается Цитадель Ледяной Короны, построенная изо льда и саронита вокруг Ледяного Трона." }, { 17.65, "Серебряный Авангард и рыцари Чёрного Клинка ведут здесь тяжёлую войну, пока Альянс и Орда готовят свои войска." }, { 28.03, "На юге проходит Серебряный Турнир, а у стен цитадели Тирион Фордринг объединяет прежних врагов в Пепельный союз для последнего штурма." } } } }
books["07caf819"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Вершина Рыцарей — высокая крепость Серебряного Авангарда в Ледяной Короне." }, { 7.78, "Крестоносцы используют её как командный пункт и готовят отсюда походы к Цитадели Ледяной Короны." }, { 16.40, "Ветер и снег скрывают стены, но внутри постоянно прибывают войска, оружие и сведения о силах Короля-лича." } } } }
books["1c2f3b44"] = { d = 31.3, v = "narrator", c = { x = { { 0.00, "Мрачный Свод — крепость рыцарей Чёрного Клинка, захваченная у Плети в ледяных горах." }, { 8.94, "Здесь неживые союзники Альянса и Орды ведут собственную кампанию против бывшего хозяина, создавая оружие и отправляя отряды к Цитадели." }, { 22.47, "Свод остаётся мрачным местом, но его стены стали частью общего фронта против Короля-лича." } } } }
books["3479cea0"] = { d = 29.6, v = "narrator", c = { x = { { 0.00, "Оплот Серебряного Авангарда — передовая крепость на южном подходе к Цитадели Ледяной Короны." }, { 9.45, "Здесь крестоносцы собирают войска, защищают дороги и готовят последний марш против Короля-лича." }, { 19.23, "Оплот соединяет Серебряный Турнир с северным фронтом и принимает тех, кто готов сражаться рядом с рыцарями Чёрного Клинка." } } } }
books["c0b03653"] = { d = 30.3, v = "narrator", c = { x = { { 0.00, "Ристалище Серебряного турнира — укреплённый лагерь на юге Ледяной Короны." }, { 7.31, "Здесь рыцари и герои Альянса, Орды и Серебряного Авангарда проходят испытания, чтобы подготовиться к штурму Цитадели." }, { 18.74, "За праздничными знамёнами скрывается настоящая война: турнир отбирает тех, кто сможет встретиться с армией Короля-лича." } } } }
books["758afc6d"] = { d = 28.8, v = "narrator", c = { x = { { 0.00, "Уступ Смерти — опорный пункт рыцарей Чёрного Клинка в Ледяной Короне." }, { 7.62, "Отсюда неживые воины ведут свою войну против Плети, сохраняя независимость от Короля-лича и готовясь к штурму его крепости." }, { 19.94, "На ледяных высотах рядом стоят дозоры, кузницы и площадки для вылазок в самое сердце врага." } } } }
books["f599b913"] = { d = 47.4, v = "narrator", c = { x = { { 0.00, "Лес Тероккар окружает Шаттрат и тянется от каменистых пустошей до древних лесов на юге Запределья." }, { 11.29, "Среди его деревьев стоят руины дренейских поселений, лагеря экспедиции и святилища, оставшиеся после войн с орками." }, { 22.38, "В небе над костяными пустошами кружат араккоа, а в глубинах леса скрываются их города и проклятые ритуальные места." }, { 33.59, "На дорогах сталкиваются Альянс и Орда, но главная опасность края — память о разрушенном Дреноре, которая всё ещё живёт в руинах и призраках." } } } }
books["c2697ade"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Бастион Аллерии — укреплённый лагерь Альянса на северо-западе Леса Тероккар." }, { 6.99, "Его солдаты охраняют дорогу к Шаттрату и следят за араккоа, которые контролируют окрестные руины." }, { 15.28, "В лагере собираются сведения о старых поселениях дренеев и о движении Орды, а патрули поддерживают связь с другими силами экспедиции." }, { 26.75, "За стенами бастиона лес быстро уступает место каменистым равнинам, где любая колонна может попасть в засаду." } } } }
books["9b6b5a88"] = { d = 46.2, v = "narrator", c = { x = { { 0.00, "Деревня Грангол'вар — разрушенное поселение на западе Леса Тероккар, у северной границы Костяных пустошей." }, { 10.22, "Её заняли члены Совета Теней: среди руин бродят мрачные призыватели, палачи и охотники." }, { 19.30, "Разведчики Альянса и Орды отправляют сюда добровольцев под маскировкой, чтобы расспросить посвящённых, работников и советников." }, { 29.12, "Но охотники способны распознать чужака даже под чужой личиной." }, { 35.67, "Выяснив, кто скрывается в деревне, разведчики требуют уничтожить приспешников Совета и их главаря — Повелителя теней Скорбного." } } } }
books["cb6cb115"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Лагерь Камнеломов — опорный пункт Орды на юге Леса Тероккар." }, { 6.91, "Рабочие и бойцы добывают камень, расчищают дороги и удерживают участок рядом с древними дренейскими руинами." }, { 17.32, "Из лагеря отправляются отряды к Шаттрату, к костяным пустошам и к землям араккоа." }, { 25.06, "Грубые укрепления постоянно приходится чинить, потому что лесные хищники, разбойники и вражеские патрули одинаково охотно проверяют его оборону." } } } }
books["dbba512c"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Перелесок Кенария — тихое святилище друидов среди деревьев Леса Тероккар." }, { 7.29, "Его защитники следят за природой Запределья и помогают лесным духам, которым угрожают война и древняя скверна." }, { 16.85, "Небольшие тропы ведут отсюда к болотистым низинам и к руинам, где следы прежних битв всё ещё заметны." }, { 25.45, "Перелесок напоминает, что даже рядом с Шаттратом остаются места, где важнее оружия становятся терпение, забота и знание живого мира." } } } }
books["cca11934"] = { d = 38.3, v = "narrator", c = { x = { { 0.00, "Скеттис — древний город араккоа на каменных плато юго-восточного Леса Тероккар." }, { 8.89, "Его башни и мосты поднимаются над костяными пустошами, а жители поклоняются мрачным силам и охраняют свои ритуальные места." }, { 20.38, "В городе сохранились следы старой культуры, но война и безумные обряды превратили его в опасное гнездо." }, { 29.44, "Над плато постоянно кружат крылатые стражи, поэтому любой путь к руинам требует осторожности и хорошей разведки." } } } }
books["96cc12c4"] = { d = 46.2, v = "narrator", c = { x = { { 0.00, "Лес Хрустальной Песни лежит в центре Нордскола, где кристаллы растут из земли и превращают деревья в светящиеся колонны." }, { 12.81, "Когда-то здесь стоял город Шандарал, построенный высшими эльфами для хранения тайной магии, но синие драконы разрушили его во время древней войны." }, { 26.96, "Теперь над лесом парит Даларан, а у его подножия Серебряный союз и Похитители Солнца заняли старые башни." }, { 37.62, "Между кристаллами остаются следы великой магии, за которую всё ещё спорят драконы и маги." } } } }
books["6f3d61d1"] = { d = 29.1, v = "narrator", c = { x = { { 0.00, "Дозор Ветрокрылой — башня Серебряного союза в Лесу Хрустальной Песни." }, { 6.89, "Высшие эльфы Альянса наблюдают отсюда за дорогами к Даларану, поддерживают свою фракцию и противостоят Похитителям Солнца." }, { 17.98, "Кристаллы вокруг башни хранят следы древней магии, но нынешний дозор занят не археологией, а борьбой за влияние и безопасность города." } } } }
books["c295c6fa"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Лагерь Похитителя Солнца — башня эльфов крови у стен парящего Даларана." }, { 7.61, "Его маги и стражи защищают интересы Кель'Таласа, наблюдают за Кирин'Тором и спорят с Серебряным союзом о будущем магии." }, { 19.22, "Под кристальными деревьями лагеря старое политическое противостояние продолжается прямо посреди войны с Малигосом и Королём-личом." } } } }
books["d18519f6"] = { d = 43.3, v = "narrator", c = { x = { { 0.00, "Леса Вечной Песни — солнечный край к северу от Луносвета, где высшие эльфы веками жили среди золотых деревьев и магических источников." }, { 13.07, "Третья война оставила на земле шрамы: Артас прошёл к Солнечному колодцу через эти леса, а его армия подняла павших эльфов." }, { 24.36, "Теперь часть леса заражена магией Плети, по дорогам бродят мертвецы, а эльфы крови охраняют оставшиеся святилища и учатся жить без привычного источника силы." }, { 38.25, "На востоке уже слышны отголоски новой борьбы за Кель'Талас." } } } }
books["f2cf6fcd"] = { d = 43.9, v = "narrator", c = { x = { { 0.00, "Луносвет — древняя столица высших эльфов, пережившая нашествие Плети и почти полное разрушение." }, { 10.24, "Король Анастериан пал у городских стен, а принц Кель'тас увёл уцелевших на поиски спасения." }, { 19.55, "Эльфы крови восстановили главные улицы и дворцы, но следы войны видны в разбитых кварталах и закрытых воротах." }, { 30.05, "В городе спорят магистры, следопыты и жрецы, ищущие путь для своего народа, пока на севере Плети и безумные эльфы продолжают угрожать Кель'Таласу." } } } }
books["4be3eccb"] = { d = 45.7, v = "narrator", c = { x = { { 0.00, "Награнд — зелёные равнины западного Запределья, где среди холмов лежат озёра и священные земли орков." }, { 10.15, "До разрушения Дренора здесь жили кланы орков и кочевые племена, а теперь маг'хары стараются сохранить старый уклад и память предков." }, { 22.73, "В Гардаре собираются силы Орды, Телаар защищает интересы Альянса, а в Ошу'гуне скрывается тайна, связанная с душами умерших дренеев." }, { 35.74, "На равнинах спорят кентавры, огры и охотники Эрнестуэя, превращая мирный край в поле постоянной борьбы." } } } }
books["d7170888"] = { d = 41.6, v = "narrator", c = { x = { { 0.00, "Гарадар — главное поселение маг'харов в Награнде и дом тех, кто сохранил старые обычаи орков." }, { 10.21, "Здесь живут семьи, шаманы и воины, которые помнят Дренор до прихода скверны." }, { 18.86, "Деревня защищает равнины от огров, кентавров и чужих армий, а её старейшины стараются не втягивать народ в новую войну." }, { 31.38, "Для маг'харов Гарадар — не просто крепость, а место, где решается, смогут ли они сохранить собственную историю." } } } }
books["67110903"] = { d = 40.4, v = "narrator", c = { x = { { 0.00, "Ошу'гун — огромная кристаллическая гора посреди Награнда, почитаемая дренеями как место покоя душ." }, { 10.59, "Внутри кристалла скрывается священный некрополь, а вокруг него ходят стада и проходят древние дороги." }, { 19.78, "Шаманы и жрецы чувствуют здесь присутствие предков, тогда как добытчики и охотники видят в горе источник редких материалов." }, { 31.63, "Ошу'гун хранит память о народе, который пережил падение Дренора и всё ещё ищет путь домой." } } } }
books["9f426ffc"] = { d = 39.8, v = "narrator", c = { x = { { 0.00, "Руины Веселого Черепа лежат среди холмов Награнда, где когда-то стояло поселение клана орков." }, { 9.60, "Теперь каменные развалины заняли огры, а старые дома напоминают о времени, когда кланы ещё спорили за равнины до прихода чужой армии." }, { 21.73, "Отсюда открывается путь к пастбищам и к опасным ущельям, поэтому руины часто становятся целью разведчиков." }, { 31.93, "Ветер гонит пыль по пустым улицам, смешивая память о прошлом с шумом новых сражений." } } } }
books["03c3ee7c"] = { d = 37.1, v = "narrator", c = { x = { { 0.00, "Телаар — главный опорный пункт Альянса в Награнде, построенный на холме среди зелёных равнин." }, { 9.47, "Дренеи и их союзники используют его как место отдыха, торговли и подготовки походов против огров и кентавров." }, { 18.94, "Вокруг города пасутся животные, а на дальних дорогах часто встречаются маг'хары и странники, ищущие безопасный путь." }, { 28.83, "Телаар старается сохранить вид мирного поселения, хотя его стены стоят в самом центре борьбы за Награнд." } } } }
books["30145870"] = { d = 38.1, v = "narrator", c = { x = { { 0.00, "Халаа — древний город в центре Награнда, за который Альянс и Орда сражаются из-за его положения и запасов ресурсов." }, { 11.30, "Улицы города переходят из рук в руки, а башни и дома становятся наблюдательными пунктами для обеих сторон." }, { 19.94, "Рядом проходят дороги к священным местам дренеев, пастбищам и лагерям огров." }, { 27.11, "Халаа показывает, как спокойные равнины могут за несколько часов превратиться в поле боя, если через них проходят важные пути." } } } }
books["6c080287"] = { d = 43.0, v = "narrator", c = { x = { { 0.00, "Низина Шолазар — тёплая зелёная котловина среди ледяного Нордскола, защищённая древними устройствами титанов." }, { 11.59, "Здесь сохранился живой уголок мира, где исследователи Несингвари охотятся на зверей, а горлоки и волвары спорят за леса и источники." }, { 24.02, "Оракулы и племя Безумного Сердца втянуты в непрерывную борьбу, и союз с одной стороной неизбежно означает вражду с другой." }, { 35.28, "После падения восточного пилона Плеть пробралась в низину, угрожая её хрупкому равновесию." } } } }
books["05cac69c"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Лагерь Эрнестуэя — охотничья стоянка исследователей в западной части Низины Шолазар." }, { 8.84, "Люди Несингвари изучают зверей котловины, прокладывают тропы и пытаются выжить среди хищников, горлоков и волваров." }, { 19.77, "Лагерь напоминает о необычном устройстве Шолазара: среди снегов Нордскола здесь всё ещё можно услышать не ледяной ветер, а звуки зелёных джунглей." } } } }
books["c94cec8b"] = { d = 31.6, v = "narrator", c = { x = { { 0.00, "Слияние рек — центральное поселение Низины Шолазар у тёплого озера." }, { 7.14, "Здесь пересекаются дороги исследователей, Оракулов и племени Безумного Сердца, пока древние механизмы титанов поддерживают жизнь в котловине." }, { 19.64, "За зелёными берегами скрываются спорящие племена и следы Плети, поэтому спокойная вода остаётся лишь видимой частью местной истории." } } } }
books["ce79c12f"] = { d = 43.9, v = "narrator", c = { x = { { 0.00, "Озеро Ледяных Оков — замёрзшее поле битвы в самом сердце Нордскола, где Альянс и Орда постоянно спорят за крепость на острове." }, { 14.07, "Победившая сторона получает доступ к древнему Хранилищу Архавона и может использовать его залы против воинов соперника." }, { 25.02, "Вокруг стен работают осадные машины, рушатся башни и поднимаются облака снега." }, { 33.44, "Для армий Нордскола это не просто крепость, а ключ к дороге между Далараном, Драконьим Погостом и Ледяной Короной." } } } }
books["5ae78519"] = { d = 41.0, v = "narrator", c = { x = { { 0.00, "Остров Кель'Данас лежит у северных берегов Кель'Таласа и хранит Солнечный колодец, источник силы народа эльфов крови." }, { 11.64, "После того как Артас осквернил колодец, остров стал опорным пунктом Кель'таса и его союзников из Пылающего Легиона." }, { 21.55, "Теперь войска Ша'тар и эльфы крови сражаются за берег, пока магистры пытаются вернуть колодцу прежнее назначение." }, { 31.61, "Над островом стоят корабли и укрепления, а в глубине цитадели враги готовят последний удар по всему Кель'Таласу." } } } }
books["1e9a8590"] = { d = 39.4, v = "narrator", c = { x = { { 0.00, "Остров Кровавой Дымки — северная часть островов Лазурной Дымки, изменённая магией разбившегося корабля дренеев." }, { 9.84, "Кристаллы и туман окрасили землю в красные и багровые тона, а леса наполнились мутировавшими зверями и чужими существами." }, { 20.74, "Дренеи укрепились в Кровавой заставе и на побережье, отбиваясь от нагов, сатиров и бежавших с острова врагов." }, { 30.07, "Среди скал лежат следы древних сил, а каждый новый лагерь показывает, как быстро чужая магия меняет живой край." } } } }
books["16d1fc47"] = { d = 45.7, v = "narrator", c = { x = { { 0.00, "Остров Лазурной Дымки стал убежищем дренеев после крушения Экзодара на берегах Азерота." }, { 9.08, "До катастрофы это были тихие острова ночных эльфов, но обломки корабля изменили леса, берега и древние кристаллы." }, { 20.72, "В деревне Кровавой Стражи и у храмов дренеи восстанавливают силы, изучают местную природу и ищут пропавших сородичей." }, { 31.99, "Между тем наги, сатиры и изменившиеся звери угрожают поселениям, а кристаллы Экзодара напоминают о далёком бегстве от Пылающего Легиона." } } } }
books["ca8e338e"] = { d = 46.2, v = "narrator", c = { x = { { 0.00, "Острогорье — суровый край северного Запределья, где острые хребты разрезают небо, а ущелья скрывают древние логова." }, { 12.70, "Здесь обитают дикие драконы, огры клана Раздробленного Хребта и племена, пережившие разрушение Дренора." }, { 22.36, "Экспедиции Альянса и Орды ищут руду, союзников и следы старых войн, но каждый лагерь стоит на земле, которую приходится отвоёвывать." }, { 35.63, "В глубине гор сохранились владения Груула и логова его прислужников, а над долинами всё ещё кружат крылатые хищники." } } } }
books["ca77061b"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Вечная роща — зелёное убежище среди каменных хребтов Острогорья." }, { 7.54, "Деревья здесь растут под защитой друидов и служат редким напоминанием о том, каким был Дренор до разрушения." }, { 17.51, "В роще живут исследователи природы и представители пеплошкурых племён, а дороги связывают её с лагерями экспедиции." }, { 28.38, "За границами зелёного островка начинаются ущелья, где огры, драконы и демоны спорят за каждый источник воды." } } } }
books["9430a348"] = { d = 41.8, v = "narrator", c = { x = { { 0.00, "Деревня Мок'Натал стоит среди ущелий Острогорья и служит домом для полукровок-орков, которые сохранили связь с клановыми традициями." }, { 13.13, "Жители охотятся, защищают свои тропы и не доверяют чужим армиям, слишком часто приходившим в их горы с приказами и обещаниями." }, { 25.34, "Рядом проходят пути к лагерям Альянса и Орды, поэтому деревня вынуждена выбирать союзников осторожно." }, { 34.31, "Её стойкость держится на родстве, знании местности и уважении к старым обычаям." } } } }
books["8ad6d767"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Оплот Громоборцев — крепость клана орков в северных горах Острогорья." }, { 7.53, "Его воины удерживают перевалы, охраняют шахты и следят за драконами, которые гнездятся на скалах." }, { 16.35, "В крепости собираются сведения о старых войнах и готовят вылазки против врагов клана, а вокруг постоянно слышен грохот кузниц." }, { 27.91, "Высота даёт оплоту защиту, но одновременно делает его заметной целью для всех, кто хочет пройти через горы." } } } }
books["8f4b9c51"] = { d = 41.2, v = "narrator", c = { x = { { 0.00, "Сильванаар — укреплённое поселение ночных эльфов на западных склонах Острогорья." }, { 9.13, "Его жители изучают местную природу, ищут следы древних сил и помогают союзникам пройти через горные тропы." }, { 19.85, "Город окружён лесом, но спокойствие здесь обманчиво: рядом действуют огры и другие опасные племена, а в небе охотятся драконы." }, { 33.45, "Сильванаар соединяет строгую военную дисциплину с заботой о редких лесах Запределья." } } } }
books["ecfc764c"] = { d = 39.3, v = "narrator", c = { x = { { 0.00, "Станция Тошли — исследовательский лагерь гномов на востоке Острогорья." }, { 7.35, "Инженеры изучают кристаллы, воздушные потоки и древние механизмы, пытаясь понять свойства горного края." }, { 17.57, "Вокруг станции проложены дороги к шахтам и скалам, но испытания часто привлекают огров и других врагов." }, { 26.95, "Здесь мир Запределья рассматривают как огромную лабораторию, где каждая находка может стать полезным изобретением или причиной нового взрыва." } } } }
books["d38fa56d"] = { d = 45.7, v = "narrator", c = { x = { { 0.00, "Полуостров Адского Пламени — выжженная северная граница Запределья, где красная пыль покрывает развалины старого Дренора." }, { 11.94, "Через этот край проходили орды Гул'дана, а теперь Цитадель Адского Пламени стала крепостью демонов и предавшихся им орков." }, { 23.21, "Альянс закрепился в Оплоте Чести, Орда — в Траллмаре, и обе стороны пытаются открыть путь к центру полуострова." }, { 34.22, "В пустошах бродят демоны, магтеридоновы войска и искалеченные временем существа, а древние врата ведут к новым войнам." } } } }
books["5394a368"] = { d = 39.1, v = "narrator", c = { x = { { 0.00, "Кенарийская застава стоит на южной окраине Полуострова Адского Пламени, среди раскалённых камней и следов разрушенной природы." }, { 12.09, "Друиды и следопыты изучают демонов, которые оскверняют землю, и пытаются вернуть жизнь в выжженные места." }, { 22.23, "Отсюда экспедиции отправляются к Цитадели Адского Пламени и к старым дорогам Дренора." }, { 29.95, "Застава невелика, но она напоминает, что даже в краю скверны борьба за природу ещё не проиграна." } } } }
books["46d00ea0"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Оплот Чести — главная крепость Альянса на Полуострове Адского Пламени." }, { 6.40, "За его стенами солдаты собираются после перехода через Тёмный портал и готовят наступление против сил Пылающего Легиона." }, { 15.45, "В крепости работают кузнецы, разведчики и целители, а дороги ведут к Цитадели Адского Пламени и окрестным лагерям орков." }, { 25.51, "Здесь особенно ясно видно, что война в Запределье началась сразу после открытия портала и быстро стала борьбой за каждую переправу и высоту." } } } }
books["e32ee392"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Соколиный дозор — укреплённый лагерь Альянса на юго-западе полуострова." }, { 6.85, "Его бойцы следят за дорогами, по которым из Цитадели Адского Пламени выходят демоны и служащие им орки." }, { 16.37, "Вокруг заставы идут разведывательные вылазки, а на её стенах готовят защиту от внезапных нападений." }, { 25.28, "Для прибывших через портал это один из первых безопасных пунктов, где можно узнать о силах врага и продолжить путь в глубь Запределья." } } } }
books["fb86f1be"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Траллмар — опорный лагерь Орды у Тёмного портала, названный в честь вождя Тралла." }, { 8.67, "Орки и их союзники собираются здесь перед походами к Цитадели Адского Пламени, разбирают сведения разведчиков и защищают дорогу через выжженную равнину." }, { 21.45, "За частоколом кипит военная работа, а за воротами начинаются земли, где демоны и орки Скверны ещё удерживают старые позиции." }, { 33.64, "Траллмар служит Орде первым домом в изменившемся Дреноре." } } } }
books["bc263d48"] = { d = 38.3, v = "narrator", c = { x = { { 0.00, "Храм Телхамат — древнее святилище дренеев в южной части полуострова." }, { 7.39, "Его кристаллические стены уцелели среди пепла и раскалённых ущелий, поэтому храм стал убежищем для тех, кто пытается пережить войну." }, { 18.85, "Дренеи хранят здесь память о родной земле и помогают путникам, направляющимся к лагерям Альянса." }, { 27.18, "Рядом всё ещё хозяйничают демоны и орки Скверны, и спокойствие святилища зависит от того, насколько далеко удастся отодвинуть врага." } } } }
books["0b54bb26"] = { d = 42.2, v = "narrator", c = { x = { { 0.00, "Призрачные земли лежат к югу от Луносвета и стали первым щитом Кель'Таласа после нашествия Плети." }, { 9.74, "Артас прошёл здесь по пути к Солнечному колодцу, оставив за собой выжженные деревни, могилы и поднятых мертвецов." }, { 19.86, "Эльфы крови удерживают заставы и пытаются вернуть дороги, но в лесах остались некрополи, банши и отряды нежити." }, { 31.35, "На западе высится крепость Транквиллион, а на востоке враги из Плети и Аманийских троллей спорят за руины старого королевства." } } } }
books["283bfb22"] = { d = 43.2, v = "narrator", c = { x = { { 0.00, "Пустоверть — разорванный край северо-восточного Запределья, где клочья земли висят в бездне под фиолетовым небом." }, { 10.80, "Магия Пустоты пронизывает воздух, а энергетические потоки питают башни и машины тех, кто пытается подчинить себе этот мир." }, { 22.04, "Кирин'Вар и другие поселения были разрушены экспериментами, демоны Легиона охраняют свои крепости, а эльфы крови Кель'таса собирают энергию для новых войн." }, { 36.31, "Только Небесный хребет и поля кристаллов напоминают, что когда-то здесь была цельная земля." } } } }
books["9cfc3eb2"] = { d = 40.2, v = "narrator", c = { x = { { 0.00, "Деревня Кирин'Вар когда-то была тихим поселением магов в Пустоверти, но эксперименты превратили её улицы в опасные руины." }, { 10.65, "Часть жителей погибла, часть исчезла, а оставшиеся здания заполнили духи и нестабильная энергия." }, { 17.70, "Исследователи пытаются понять, что произошло, и найти следы тех, кто использовал деревню в своих целях." }, { 28.20, "Среди пустых домов до сих пор работают магические устройства, поэтому даже короткая прогулка может закончиться встречей с последствиями старого эксперимента." } } } }
books["0a4e4033"] = { d = 42.4, v = "narrator", c = { x = { { 0.00, "Зона пятьдесят два — шумный торговый и инженерный лагерь гоблинов в центре Пустоверти." }, { 8.37, "Здесь продают детали, добывают энергию и принимают заказы от тех, кто готов рискнуть в разорванном краю." }, { 18.07, "Башни, генераторы и воздушные платформы растут вокруг старых руин, а деловые переговоры легко сменяются аварией или налётом." }, { 30.08, "Этот лагерь живёт по правилам выгоды, но его жители понимают: без взаимной помощи среди пустоты не выживет даже самый ловкий торговец." } } } }
books["e8495129"] = { d = 39.2, v = "narrator", c = { x = { { 0.00, "Штормовая Вершина — возвышенное святилище на краю Пустоверти, где силы Пылающего Легиона и их союзники следят за потоками энергии." }, { 13.21, "Башни стоят над бездной, а вокруг них бушуют фиолетовые вихри и разряды магии." }, { 20.89, "Путники видят здесь холодную красоту разрушенного мира, но для разведчиков это опасная крепость, связанная с порталами и наблюдением за всеми дорогами Пустоверти." }, { 34.54, "Любая ошибка на её мостах может стоить жизни." } } } }
books["0b043b55"] = { d = 47.7, v = "narrator", c = { x = { { 0.00, "Ревущий фьорд — восточный берег Нордскола, где тёмные леса обрываются к холодному морю." }, { 11.21, "В Валгарде люди и дворфы хранят память о первых воинах, оставшихся здесь после похода Артаса и Мурадина Бронзоборода." }, { 23.71, "На другой стороне фьорда Новая Агамонд стала опорой Отрёкшихся, а врукулы Утгардской крепости готовят набеги на чужие берега." }, { 37.37, "Между поселениями идут разведка и война, пока экспедиции пытаются понять, откуда пришёл этот древний народ великанов." } } } }
books["ab60b854"] = { d = 27.6, v = "narrator", c = { x = { { 0.00, "Аптекарский посёлок — лагерь Отрёкшихся на юго-западе Ревущего фьорда." }, { 7.19, "Аптекари Длани Возмездия работают здесь над чумой и снабжают передовые отряды, пока разведчики следят за дорогами к врукулам." }, { 18.02, "За внешней тишиной лагеря скрывается опасная лаборатория, где война превращается в алхимический эксперимент." } } } }
books["4d2eebc7"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Валгард — порт Альянса на берегу Ревущего фьорда, откуда экспедиция ведёт войну с врукулами." }, { 8.93, "Люди, дворфы и их союзники укрепили старую гавань, чтобы принимать корабли из Менетила и снабжать передовые заставы." }, { 19.35, "В окрестностях находят следы похода Артаса и Мурадина Бронзоборода, а рядом возвышается Утгардская крепость." }, { 28.62, "За стенами Валгарда готовят новые вылазки, потому что фьорд не терпит слабости." } } } }
books["5b02e65d"] = { d = 41.9, v = "narrator", c = { x = { { 0.00, "Искаал — поселение тускарров на северных берегах Ревущего фьорда." }, { 7.48, "Его жители держатся за море, рыболовство и старые обычаи, пока война вокруг всё сильнее сжимает их земли." }, { 18.81, "Из деревни тускарры наблюдают за побережьем и помогают сородичам, оказавшимся между врукулами и чужими армиями." }, { 29.14, "Здесь особенно ясно видно, как народ моря пытается сохранить привычную жизнь на континенте, где каждый берег стал линией фронта." } } } }
books["7d569117"] = { d = 38.0, v = "narrator", c = { x = { { 0.00, "Камагуа — крупная гавань тускарров на острове Копий у северо-западного берега Ревущего фьорда." }, { 9.39, "В домах, похожих на больших морских зверей, жители укрываются от холода и принимают странников из разных уголков Нордскола." }, { 21.03, "Здесь чинят лодки, торгуют рыбой и поддерживают путь к Драконьему Погосту." }, { 28.97, "Камагуа сохраняет мирный уклад, хотя вокруг неё враждуют Отрёкшиеся, Альянс и врукулы." } } } }
books["b9021e87"] = { d = 29.7, v = "narrator", c = { x = { { 0.00, "Крепость Вилдервар — укрепление Альянса на восточном берегу Ревущего фьорда." }, { 8.41, "Люди и дворфы держат здесь гарнизон против врукулов, охраняют дороги и поддерживают связь с Валгардом." }, { 18.70, "Крепость стоит среди лесов и скал, где любая разведывательная вылазка может привести к древним стенам Утгарда или к лагерям врага." } } } }
books["a544e8fb"] = { d = 32.3, v = "narrator", c = { x = { { 0.00, "Крепость Западной Стражи — главная база Альянса на западном берегу Ревущего фьорда." }, { 8.43, "Её гарнизон охраняет побережье, принимает корабли и отправляет отряды против врукулов и Отрёкшихся." }, { 18.37, "За стенами сходятся дороги к Валгарду, Камагуа и северным лесам, поэтому крепость служит одновременно портом, штабом и последним безопасным рубежом." } } } }
books["71dd4cac"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "Крепость Утгард — древняя твердыня врукулов над заливом Кинжалов." }, { 7.00, "Её стены пережили века, а теперь внутри собираются воины народа великанов, готовые вернуть себе власть над фьордом." }, { 18.05, "В подземных залах пробуждаются мёртвые и куются планы набегов, пока чужие армии пытаются понять происхождение врукулов." }, { 29.94, "Для Валгарда и других поселений крепость остаётся главным источником угрозы на восточном берегу." } } } }
books["af846ee0"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Лагерь Возмездия — передовая крепость Длани Возмездия на восточном берегу Ревущего фьорда." }, { 9.09, "Отсюда Отрёкшиеся следят за Утгардской крепостью и наносят удары по тем, кто мешает их походу в Нордскол." }, { 18.69, "В лагере смешались алхимики, разведчики и солдаты, а рядом с палатками стоят орудия и приготовленные припасы." }, { 29.14, "Для Альянса это опасный сосед, а для Отрёкшихся — плацдарм в войне против Короля-лича." } } } }
books["e9707de3"] = { d = 29.6, v = "narrator", c = { x = { { 0.00, "Лагерь Заиндевевшего Копыта — северная стоянка таунка, присоединившихся к экспедиции Орды." }, { 9.92, "Воины и охотники следят за перевалами Ревущего фьорда и помогают сородичам, оказавшимся под угрозой врукулов и Плети." }, { 21.39, "Отсюда начинаются дороги к Седым холмам и другим опорным пунктам Орды в Нордсколе." } } } }
books["75a319e8"] = { d = 36.3, v = "narrator", c = { x = { { 0.00, "Новый Агамонд — поселение Отрёкшихся на юге Ревущего фьорда." }, { 6.71, "Его жители используют старые названия Тирисфаля и строят здесь опорный пункт для войск Длани Возмездия." }, { 16.37, "За частоколом работают алхимики, готовящие новые образцы чумы, а разведчики следят за врукулами и войсками Альянса." }, { 27.38, "Поселение кажется спокойным только издали: внутри него война смешалась с опасными экспериментами." } } } }
books["05cb5101"] = { d = 44.4, v = "narrator", c = { x = { { 0.00, "Седые холмы — огромный хвойный лес на западе Нордскола, где среди деревьев сохранились древние тропы и святилища медведей." }, { 12.88, "В центре стоит Вордрассил, погибшее мировое древо, чьи корни скрывают следы опасной силы." }, { 22.71, "Фурболги пытаются вернуть лес себе, но их земли теснит война, а железные дворфы вырубают деревья ради своих машин." }, { 34.62, "В окрестностях Среброрука вновь появился культ Волка, и тень Аргула превращает охотников в чудовищ." } } } }
books["8f2270b9"] = { d = 28.8, v = "narrator", c = { x = { { 0.00, "Крепость Завоевателей — опорный пункт Орды в южных Седых холмах." }, { 7.35, "Воины используют её для нападений на Плеть, контроля лесных дорог и давления на соседние силы Альянса." }, { 17.58, "За частоколом собираются припасы и отряды, а за воротами начинаются земли, где древний лес скрывает сразу несколько фронтов." } } } }
books["0779d8b3"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Лагерь Уанква — стоянка Орды на юго-востоке Седых холмов." }, { 7.11, "Орки и их союзники следят за лесными дорогами, ведут переговоры с таунка и сражаются с врагами, которые угрожают гарнизонам Нордскола." }, { 18.62, "Лагерь стоит на границе большого леса, поэтому его дозоры первыми замечают движение Альянса, фурболгов и Плети." } } } }
books["7cc5ce34"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Лагерь дружины Западного Края — передовая стоянка Альянса в восточной части Седых холмов." }, { 8.77, "Солдаты следят за дорогами, охраняют экспедиции и пытаются удержать лес от войск Орды и Плети." }, { 18.44, "Название напоминает о старой дружине, но задачи лагеря просты: разведка, снабжение и постоянная готовность к нападению из чащи." } } } }
books["603ab695"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Приют Янтарной Сосны — поселение Альянса среди хвойных лесов Седых холмов." }, { 8.47, "Люди и дворфы держат здесь гарнизон, защищают дороги и пытаются остановить племена фурболгов, всё сильнее страдающих от войны и порчи." }, { 21.32, "Отсюда экспедиции направляются к Вордрассилу, Среброрукому и дальним заставам Нордскола." } } } }
books["f7a16806"] = { d = 35.7, v = "narrator", c = { x = { { 0.00, "Слезы Фордрассила — место у корней павшего мирового древа в Седых холмах." }, { 7.39, "Когда-то здесь пытались укрыть лес от чужой силы, но дерево не выдержало болезни, проникшей в его землю и корни." }, { 16.90, "Теперь среди стволов живут фурболги, охотники и порождения леса, а следопыты изучают признаки осквернения." }, { 26.79, "Каждая тропа здесь напоминает о том, как даже благородное древо может стать источником беды для всего края." } } } }
books["5e578471"] = { d = 43.8, v = "narrator", c = { x = { { 0.00, "Шаттрат — разрушенная столица дренеев, которую пророк Велен превратил в убежище для всех, кто противостоит Пылающему Легиону." }, { 12.30, "Когда-то орки разграбили город, но его руины заново заселили дренеи, наару и беженцы со всего Запределья." }, { 22.53, "В Нижнем городе живут изгнанники, торговцы и искатели удачи, а в Террасе Света собираются силы, верящие в возвращение мира." }, { 34.83, "Вражда Алдоров и Провидцев напоминает, что даже под защитой Света союзники не забыли старые распри." } } } }
books["1d9542a9"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "Возвышенность Алдоров — высокий квартал Шаттрата, где живут дренеи, жрецы и союзники пророка Велена." }, { 10.03, "С террас открывается вид на разрушенные улицы города, а в храмах хранят память о светлых временах и молятся о защите Запределья." }, { 21.66, "Алдоры помогают беженцам и поддерживают силы, которые выступают против демонов." }, { 28.82, "Их квартал строг и спокоен, но под этим спокойствием чувствуется давняя вражда с эльфами крови." } } } }
books["8c096553"] = { d = 39.9, v = "narrator", c = { x = { { 0.00, "Нижний город — тесный квартал под главными террасами Шаттрата, куда стекаются торговцы, изгнанники и жители, не нашедшие места среди великих фракций." }, { 14.06, "Здесь работают ремесленники, таверны и рынки, а за каждым поворотом встречаются следы чужих войн." }, { 23.21, "Городская стража старается удерживать порядок, но Нижний город живёт собственной жизнью." }, { 30.73, "Для одних это убежище, для других — удобное место, чтобы скрыть сделку или начать рискованное путешествие." } } } }
books["8dbc429f"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Терраса Света — центральный священный квартал Шаттрата, где наару и их союзники принимают беженцев со всего Запределья." }, { 11.98, "Здесь находятся главные святилища, залы собраний и дороги к другим частям города." }, { 20.04, "Свет наару защищает улицы от демонов, но не может сразу примирить всех, кто ищет в городе убежище." }, { 29.65, "На террасе встречаются послы, жрецы и военачальники, обсуждающие, как остановить новую войну." } } } }
books["e11de0bd"] = { d = 41.2, v = "narrator", c = { x = { { 0.00, "Ярус Провидцев — квартал эльфов крови в Шаттрате, построенный на террасах напротив владений Алдоров." }, { 9.77, "Его маги и жрецы служат своим покровителям и стараются сохранить влияние народа, который пережил потерю Солнечного колодца." }, { 20.99, "На улицах стоят кристаллы, палатки торговцев и посты наблюдателей, а за внешней вежливостью продолжается спор о будущем города." }, { 32.60, "Ярус показывает, что даже в убежище, созданном ради мира, старые союзы остаются непрочными." } } } }
books["23a677b5"] = { d = 42.2, v = "narrator", c = { x = { { 0.00, "Экзодар — огромный корабль дренеев, потерпевший крушение на островах у берегов Калимдора." }, { 9.92, "Он был частью странствующего межзвёздного флота, который бежал от Пылающего Легиона и искал новый дом." }, { 19.37, "После катастрофы корабль стал столицей дренеев, а его кристаллические залы превратились в мастерские, храмы и жилые кварталы." }, { 31.45, "Часть систем всё ещё повреждена, но пророк Велен и его народ используют Экзодар как опору для помощи союзникам и борьбы с демонами." } } } }
